WITH agg AS ( SELECT a.expert_id AS agent_id, date_trunc('day', CAST(a."date" AS TIMESTAMP)) AS period, LOWER(a.metric) AS metric, a.icp_client, a.site, SUM(a.numerator) AS numerator, SUM(a.denominator) AS denominator FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-02-20' AND DATE '2026-02-25' AND LOWER(a.metric) IN ( 'crt' ) AND LOWER(a.icp_client) IN ( 'pss-verizon' ) GROUP BY 1,2,3,4,5 ) SELECT agent_id, CAST(period AS DATE) AS period, metric, icp_client, site, CAST(numerator AS DOUBLE) AS numerator, CAST(denominator AS DOUBLE) AS denominator, ROUND( COALESCE( CAST(numerator AS DOUBLE) / NULLIF(CAST(denominator AS DOUBLE), 0.0), 0.000 ), 3 ) AS calc FROM agg
